package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.nio.file.*;
/** Pure per-phase budget and typed observation tests; no live permit is minted. */
public class RootPhaseSourceBudgetTest {
    private static final RootCaptureScope.Phase FIRST=RootCaptureScope.Phase.FIRST,SECOND=RootCaptureScope.Phase.SECOND;
    @Test public void threePrePlusOnePostAndNoReplay(){Object owner=new Object();var b=new CaptureSessionRuntime.SourceReadBudget(owner,FIRST,()->true);assertTrue(b.claim(owner,FIRST));for(int i=0;i<3;i++)assertTrue(b.pre(owner,FIRST));assertFalse(b.pre(owner,FIRST));assertTrue(b.post(owner,FIRST));assertFalse(b.post(owner,FIRST));assertFalse(b.pre(owner,FIRST));assertFalse(b.claim(owner,FIRST));}
    @Test public void exactBeforeAndAfterBudgetsDoNotStealEachOther(){Object first=new Object(),second=new Object();var a=new CaptureSessionRuntime.SourceReadBudget(first,FIRST,()->true);var b=new CaptureSessionRuntime.SourceReadBudget(second,SECOND,()->true);assertTrue(a.claim(first,FIRST));assertTrue(b.claim(second,SECOND));for(int i=0;i<3;i++){assertTrue(a.pre(first,FIRST));assertTrue(b.pre(second,SECOND));}assertTrue(a.post(first,FIRST));assertTrue(b.post(second,SECOND));assertFalse(a.pre(second,SECOND));}
    @Test public void wrongOwnerClaimCannotBecomeAuthorityLater(){Object owner=new Object();var b=new CaptureSessionRuntime.SourceReadBudget(owner,FIRST,()->true);assertFalse(b.claim(new Object(),FIRST));assertFalse(b.claim(owner,FIRST));assertFalse(b.pre(owner,FIRST));}
    @Test public void wrongPhaseClaimCannotBecomeAuthorityLater(){Object owner=new Object();var b=new CaptureSessionRuntime.SourceReadBudget(owner,FIRST,()->true);assertFalse(b.claim(owner,SECOND));assertFalse(b.claim(owner,FIRST));assertFalse(b.post(owner,FIRST));}
    @Test public void noPostBeforePreAndNoLaterRepair(){Object owner=new Object();var b=new CaptureSessionRuntime.SourceReadBudget(owner,FIRST,()->true);assertTrue(b.claim(owner,FIRST));assertFalse(b.post(owner,FIRST));assertFalse(b.pre(owner,FIRST));}
    @Test public void cancelledOrExpiredBudgetDoesNotRead(){Object owner=new Object();AtomicBoolean active=new AtomicBoolean(true);var b=new CaptureSessionRuntime.SourceReadBudget(owner,FIRST,active::get);assertTrue(b.claim(owner,FIRST));assertTrue(b.pre(owner,FIRST));active.set(false);assertFalse(b.pre(owner,FIRST));assertFalse(b.post(owner,FIRST));}
    @Test public void exceptionIsUnknownNotReadAuthority(){Object owner=new Object();var b=new CaptureSessionRuntime.SourceReadBudget(owner,FIRST,()->{throw new SecurityException();});assertFalse(b.claim(owner,FIRST));assertFalse(b.pre(owner,FIRST));}
    @Test public void budgetRequiresAClaim(){Object owner=new Object();var b=new CaptureSessionRuntime.SourceReadBudget(owner,FIRST,()->true);assertFalse(b.pre(owner,FIRST));assertFalse(b.post(owner,FIRST));}
    private static ReadOnlyTwoStageRun.Observation observation(boolean family,boolean invalid){
        var c=family?ReadOnlyTwoStageRun.Capture.moreFamilyDiagnostic(new Object(),"family",AutonomousCardFixture.W,AutonomousCardFixture.H,0,1000,()->false)
            :new ReadOnlyTwoStageRun.Capture(new Object(),ReadOnlyTwoStageRun.Phase.FIRST,"quote",AutonomousCardFixture.W,AutonomousCardFixture.H,0,1000,()->false);
        var rows=AutonomousCardFixture.rows(false,false);if(invalid)rows.clear();
        return c.prepare(AutonomousCardFixture.pixels(false,false),AutonomousCardFixture.W,AutonomousCardFixture.H,rows,()->false);
    }
    @Test public void twoCardObservedFamilyCanPassLivePageGate(){assertTrue(CaptureSessionRuntime.rootFamilyPreflightPage(observation(true,false)));}
    @Test public void quoteCannotPassNewFamilyGateEvenWhenLegacyFixtureAccepts(){var o=observation(false,false);assertTrue(CaptureSessionRuntime.rootPreflightPage(o));assertFalse(CaptureSessionRuntime.rootFamilyPreflightPage(o));}
    @Test public void holdOrAbsentNativeDoesNotMintLiveFamilyPass(){assertFalse(CaptureSessionRuntime.rootFamilyPreflightPage(null));assertFalse(CaptureSessionRuntime.rootFamilyPreflightPage(observation(true,true)));}
    private static String source(String name)throws Exception {return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",name));}
    @Test public void livePermitIsPrivateExactGrantPhaseAndOwner()throws Exception {String s=source("CaptureSessionRuntime.java");assertTrue(s.contains("private RootSourceReadPermit(CaptureSessionRuntime run"));assertTrue(s.contains("run.grant==exactGrant&&run.requestOwner==exactOwner&&run.rootPhase==exactPhase"));assertTrue(s.contains("RealCaptureClaim.live(exactGrant)&&run.rootEpochHeld&&run.rootAuthorityLive()&&run.rootCurrent()"));assertEquals(4,s.split("new RootSourceReadPermit\\(",-1).length-1);assertTrue(s.contains("run.rootCleanReceipt.liveTransport()"));}
    @Test public void sourceBudgetNeverUsesLegacyNavigationCounter()throws Exception {String s=source("ReviewBingNavigation.java");assertTrue(s.contains("rootSourcePermit==null&&rootRecoveryPermit==null&&rootCurrentPermit==null&&(selectedPendingNavigation?PAIRS.incrementAndGet()>12:readOnlyGuard!=null?READ_ONLY_PAIRS.incrementAndGet()>4"));assertTrue(s.contains("PAIRS.incrementAndGet()>12"));assertTrue(s.contains("permit.claimReader()"));assertTrue(s.contains("!sourceAuthorized||!rootSourcePermit.current()"));assertTrue(s.contains("rootSourcePermit.readPre()"));assertTrue(s.contains("rootSourcePermit.readPost()"));assertFalse(s.contains(".set(0)"));}
    @Test public void sourcePostAndQuarantineRecheckPrecedeAnyActor()throws Exception {String s=source("CaptureSessionRuntime.java");String close=s.substring(s.indexOf("private void closeRootOnOwner()"),s.indexOf("boolean rootPublicationCurrent()"));assertTrue(close.indexOf("acceptRootSourcePostcheck()")<close.indexOf("autonomousRun.acceptAfterCleanup"));assertTrue(close.indexOf("finally{resources=rootResourcesAfterPostcheck")<close.indexOf("autonomousRun.acceptAfterCleanup"));assertTrue(close.contains("else if(rootPreflightSourceConfirmed&&resources)"));assertTrue(close.contains("autonomousRun.cancel();rootStage=\"SOURCE_POSTCHECK_REJECTED\""));}
}